{"content":"1|//! MutationEngine-owned durable native creation. No retry ever repeats POST.
2|use anyhow::{Context, Result, ensure};
3|use op_cozo_store::{NativeCreationRecord, NativeCreationRequest};
4|use op_plugins::state_plugins::incus::{self, IncusRootRepairBackend};
5|use serde_json::{Value, json};
6|use sha2::{Digest, Sha256};
7|use crate::mutation_engine::MutationEngine;
8|
9|pub(crate) async fn records(engine: &MutationEngine) -> Result<Vec<NativeCreationRecord>> {
10|    let cozo = engine.identity_sled_store()?.cozo().clone();
11|    Ok(tokio::task::spawn_blocking(move || cozo.native_creation_records()).await??)
12|}
13|
14|pub(crate) fn request(operation: &str, actor: &str, session: &str, genesis: &str,
15|    kind: &str, target: &str, body: Value) -> Result<NativeCreationRequest> {
16|    ensure!(body.is_object() && body.get("name").is_none(), "native name is server assigned");
17|    let plugin = match kind { "identity" => "identity_sled", "project" => "project", "incus" => "incus",
18|        _ => anyhow::bail!("unknown native owner") };
19|    let pin = crate::sealed_schema_reader::read_manifest_pinned_schema_document(
20|        &crate::sealed_schema_reader::blob_catalog_dir_from_env(), plugin)?;
21|    let request_json = serde_json::to_string(&body)?;
22|    let request_digest = format!("{:x}", Sha256::digest(request_json.as_bytes()));
23|    Ok(NativeCreationRequest { operation_id: operation.into(), actor_id: actor.into(),
24|        caller_session: session.into(), caller_genesis: genesis.into(), owner_kind: kind.into(),
25|        logical_target: target.into(), schema_hash: pin.schema_hash, request_digest, request_json })
26|}
27|
28|async fn admit(engine: &MutationEngine, request: &NativeCreationRequest) -> Result<()> {
29|    let (plugin, method, capability) = match request.owner_kind.as_str() {
30|        "identity" => ("identity_sled", "prepare_container", "identity_sled.write"),
31|        "project" => ("project", "create", "project.create"),
32|        "incus" => ("incus", "create_instance", "cap.service.incus.instance.create@v1"),
33|        _ => anyhow::bail!("unknown native owner"),
34|    };
35|    crate::method_contract_admission::admit_compiled_method(plugin, method, Some(capability))?;
36|    let pin = crate::sealed_schema_reader::read_manifest_pinned_schema_document(
37|        &crate::sealed_schema_reader::blob_catalog_dir_from_env(), plugin)?;
38|    ensure!(pin.schema_hash == request.schema_hash, "native creation seal changed; explicit reconciliation required");
39|    ensure!(crate::interceptor::load_capability_grants(&request.actor_id).contains(capability),
40|        "native creation requires current exact-principal grant");
41|    let current = engine.session_context_for_actor(&request.actor_id).await
42|        .context("native creation caller session missing")?;
43|    ensure!(current.session_id == request.caller_session && current.genesis_hex == request.caller_genesis,
44|        "native creation caller session changed");
45|    Ok(())
46|}
47|
48|/// Caller holds lifecycle (if applicable), then host observation lock. The
49|/// durable intent is committed and flushed before the sole POST permission.
50|pub(crate) async fn create_locked(engine: &MutationEngine, request: NativeCreationRequest)
51|    -> Result<(NativeCreationRecord, bool)> {
52|    admit(engine, &request).await?;
53|    let native = IncusRootRepairBackend::local();
54|    let before = native.default_project_state().await?;
55|    if request.owner_kind == "project" {
56|        let prior = records(engine).await?;
57|        ensure!(!before.instances.iter().any(|i|
58|            (i.name == request.logical_target || i.config.as_ref().is_some_and(|c|
59|                c.get("user.opdbus.project_id") == Some(&request.logical_target)))
60|            && !prior.iter().any(|r| r.name == i.name && r.request.operation_id == request.operation_id)),
61|            "existing project native binding must not be recreated");
62|    }
63|    let names = before.instances.iter().map(|i| i.name.clone()).collect::<Vec<_>>();
64|    let cozo = engine.identity_sled_store()?.cozo().clone();
65|    let (record, fresh) = tokio::task::spawn_blocking(move || cozo.reserve_native_creation(request, &names)).await??;
66|    // Any failure from here retains the fence, including definite provider
67|    // errors. An absent object is not proof that an earlier POST was rejected.
68|    if fresh {
69|        admit(engine, &record.request).await?;
70|        let mut body: Value = serde_json::from_str(&record.request.request_json)?;
71|        body["name"] = record.name.clone().into();
72|        body["config"]["user.opdbus.creation_operation"] = record.request.operation_id.clone().into();
73|        body["config"]["user.opdbus.creation_digest"] = record.request.request_digest.clone().into();
74|        incus::create_reserved_native(&body).await
75|            .context("native POST outcome requires reconciliation; reservation retained")?;
76|    }
77|    let record = reconcile_locked(engine, record).await?;
78|    Ok((record, !fresh))
79|}
80|
81|pub(crate) async fn reconcile_locked(engine: &MutationEngine, record: NativeCreationRecord)
82|    -> Result<NativeCreationRecord> {
83|    admit(engine, &record.request).await?;
84|    let native = IncusRootRepairBackend::local();
85|    let (raw, _) = native.instance(&record.name).await
86|        .context("reserved native instance absent or unreadable; POST will not be repeated")?;
87|    let body: Value = serde_json::from_str(&record.request.request_json)?;
88|    ensure!(raw["name"] == record.name && raw["type"] == body["type"]
89|        && raw["config"]["user.opdbus.creation_operation"] == record.request.operation_id
90|        && raw["config"]["user.opdbus.creation_digest"] == record.request.request_digest,
91|        "native creation ownership markers differ");
92|    if record.phase != "complete" {
93|        ensure!(raw["status"] == "Stopped" && raw["status_code"] == 102
94|            && raw["profiles"] == body["profiles"] && raw["devices"] == body["devices"],
95|            "native preparation is not the pinned stopped definition");
96|        if record.request.owner_kind == "identity" {
97|            ensure!(raw["expanded_config"]["security.privileged"] == "false"
98|                && raw["expanded_config"]["security.nesting"] == "false"
99|                && raw["expanded_config"]["boot.autostart"] == "false"
100|                && raw["expanded_config"]["raw.lxc"] == body["config"]["raw.lxc"],
101|                "expanded native identity security differs");
102|            let expanded = raw["expanded_devices"].as_object().context("expanded devices absent")?;
103|            ensure!(expanded.len() == 4 && expanded.get("root") == body["devices"].get("root")
104|                && expanded.get("runtime-run") == body["devices"].get("runtime-run")
105|                && expanded.get("fuse") == body["devices"].get("fuse")
106|                && expanded.get("lungs-socket-dir") == Some(&json!({"type":"disk", "source":"/run/opdbus/lungs",
107|                    "path":"/run/opdbus/lungs", "readonly":"true"})), "expanded identity devices differ");
108|        }
109|        for (key, value) in body["config"].as_object().context("creation config missing")? {
110|            ensure!(raw["config"].get(key) == Some(value), "native creation config differs");
111|        }
112|    }
113|    let native_uuid = raw["config"]["volatile.uuid"].as_str().context("native UUID absent")?.to_owned();
114|    ensure!(uuid::Uuid::parse_str(&native_uuid)?.to_string() == native_uuid, "noncanonical native UUID");
115|    let cozo = engine.identity_sled_store()?.cozo().clone();
116|    let pinned = record.clone();
117|    let bound = tokio::task::spawn_blocking(move || cozo.bind_native_creation(&pinned, &native_uuid)).await??;
118|    let snapshot = native.default_project_state().await?;
119|    let instance = snapshot.instances.iter().find(|i| i.name == bound.name)
120|        .context("created instance missing from full readback")?;
121|    ensure!(serde_json::to_value(instance)? == serde_json::to_value(incus::IncusPlugin::instance_from_native_metadata(raw)?)?,
122|        "native instance changed during full readback");
123|    crate::incus_observer::publish_repair_readback_locked(engine, &snapshot).await?;
124|    let cozo = engine.identity_sled_store()?.cozo().clone();
125|    Ok(tokio::task::spawn_blocking(move || cozo.complete_native_creation(&bound)).await??)
126|}
127|
128|pub(crate) async fn dispatch(engine: &MutationEngine, method: &str, args: &Value,
129|    actor: &str, session: Option<&str>, genesis: Option<&str>) -> Result<Value> {
130|    let session = session.context("native creation requires verified session")?.to_owned();
131|    let genesis = genesis.context("native creation requires verified genesis")?.to_owned();
132|    let engine = engine.clone();
133|    let method = method.to_owned();
134|    let args = args.clone();
135|    let actor = actor.to_owned();
136|    tokio::spawn(async move {
137|        let _host = engine.lock_host_observation().await;
138|        let (record, replayed) = if method == "create_instance" {
139|            let input: incus::CreateInstanceInput = serde_json::from_value(args)?;
140|            let body = incus::native_creation_body(&input)?;
141|            let request = request(&input.operation_id, &actor, &session, &genesis,
142|                "incus", &input.operation_id, body)?;
143|            create_locked(&engine, request).await?
144|        } else {
145|            let input: incus::ReconcileNativeCreationInput = serde_json::from_value(args)?;
146|            let record = records(&engine).await?.into_iter()
147|                .find(|r| r.request.operation_id == input.operation_id)
148|                .context("native creation operation not found")?;
149|            ensure!(record.request.owner_kind == "incus" && record.request.actor_id == actor
150|                && record.request.caller_session == session && record.request.caller_genesis == genesis,
151|                "native creation operation belongs to another owner");
152|            (reconcile_locked(&engine, record).await?, true)
153|        };
154|        Ok(json!({"name":record.name,"operation_id":record.request.operation_id,
155|            "native_uuid":record.native_uuid,"phase":record.phase,"replayed":replayed,
156|            "created":true,"changes":[]}))
157|    }).await.context("native creation owner failed; reconcile the same operation")?
