{"content":"1|//! Global native-name allocation. Never infer a counter from provider names.
2|//! A committed intent is a permanent fence until exact readback is published.
3|use super::*;
4|
5|#[derive(Clone, Debug, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
6|#[serde(deny_unknown_fields)]
7|pub struct NativeCreationRequest {
8|    pub operation_id: String,
9|    pub actor_id: String,
10|    pub caller_session: String,
11|    pub caller_genesis: String,
12|    pub owner_kind: String,
13|    pub logical_target: String,
14|    pub schema_hash: String,
15|    pub request_digest: String,
16|    pub request_json: String,
17|}
18|
19|#[derive(Clone, Debug, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
20|#[serde(deny_unknown_fields)]
21|pub struct NativeCreationRecord {
22|    pub request: NativeCreationRequest,
23|    pub number: i64,
24|    pub name: String,
25|    pub phase: String,
26|    pub native_uuid: String,
27|}
28|
29|pub fn is_numbered_native_name(name: &str) -> bool {
30|    name.strip_prefix("ID-").is_some_and(|number| {
31|        number.parse::<i64>().is_ok_and(|n| n > 0 && n.to_string() == number)
32|    })
33|}
34|
35|fn records(tx: &MultiTransaction) -> std::result::Result<Vec<NativeCreationRecord>, CozoError> {
36|    query(tx, "?[document,operation_id] := *native_container_creations{document,operation_id}", Params::new())?
37|        .rows.iter().map(|row| {
38|            let record: NativeCreationRecord = serde_json::from_str(&string(row, 0)?)?;
39|            if string(row, 1)? != record.request.operation_id
40|                || record.request.schema_hash.is_empty()
41|                || !valid_root_repair_digest(&record.request.request_digest)
42|                || record.number <= 0 || record.name != format!("ID-{}", record.number)
43|                || !matches!(record.phase.as_str(), "intent" | "bound" | "complete")
44|                || (record.phase != "intent" && uuid::Uuid::parse_str(&record.native_uuid)
45|                    .map_or(true, |id| id.to_string() != record.native_uuid))
46|            {
47|                return Err(err("native creation journal is corrupt"));
48|            }
49|            Ok(record)
50|        }).collect()
51|}
52|
53|pub(super) fn binding_in_tx(tx: &MultiTransaction, name: &str)
54|    -> std::result::Result<Option<NativeCreationRecord>, CozoError>
55|{
56|    let rows = records(tx)?;
57|    sequence(tx, &rows)?;
58|    let mut found = rows.into_iter().filter(|row| row.name == name);
59|    let result = found.next();
60|    if found.next().is_some() { return Err(err("duplicate native name binding")); }
61|    Ok(result)
62|}
63|
64|pub(super) fn validate_identity_binding(tx: &MultiTransaction, row: &IdentitySledRecord)
65|    -> std::result::Result<(), CozoError>
66|{
67|    if row.instance_json.is_empty() { return Ok(()); }
68|    let instance: Value = serde_json::from_str(&row.instance_json)?;
69|    let name = instance["name"].as_str().unwrap_or_default();
70|    if !is_numbered_native_name(name) { return Ok(()); }
71|    let binding = binding_in_tx(tx, name)?.ok_or_else(|| err("numbered identity has no durable native binding"))?;
72|    if binding.phase != "complete" || binding.request.owner_kind != "identity"
73|        || binding.request.logical_target != row.session_id
74|        || instance["config"]["volatile.uuid"] != binding.native_uuid
75|        || instance["config"]["user.opdbus.creation_operation"] != binding.request.operation_id
76|        || instance["config"]["user.opdbus.creation_digest"] != binding.request.request_digest
77|        || instance["config"]["user.opdbus.session_id"] != row.session_id
78|        || instance["config"]["user.opdbus.wireguard_public_key"] != row.wireguard_pubkey
79|        || row.principal_kind.as_deref() != Some("service")
80|    { return Err(err("numbered identity native binding differs")); }
81|    Ok(())
82|}
83|
84|fn put(tx: &MultiTransaction, record: &NativeCreationRecord) -> std::result::Result<(), CozoError> {
85|    query(tx, "?[operation_id,document] <- [[$op,$doc]] :put native_container_creations {operation_id => document}",
86|        BTreeMap::from([
87|            ("op".into(), DataValue::Str(record.request.operation_id.as_str().into())),
88|            ("doc".into(), DataValue::Str(serde_json::to_string(record)?.into())),
89|        ]))?;
90|    Ok(())
91|}
92|
93|fn sequence(tx: &MultiTransaction, rows: &[NativeCreationRecord])
94|    -> std::result::Result<(i64, String), CozoError>
95|{
96|    let result = query(tx, "?[next,pending] := *native_container_sequence{key,next,pending}, key = 'default'", Params::new())?;
97|    let (next, pending) = match result.rows.as_slice() {
98|        [] if rows.is_empty() => {
99|            let marker = query(tx, "?[completed] := *schema_migrations{name,completed}, name = 'native-container-sequence-v1'", Params::new())?;
100|            if !marker.rows.is_empty() { return Err(err("native creation sequence is missing; refusing reset")); }
101|            (1, String::new())
102|        }
103|        [row] => (integer(row, 0)?, string(row, 1)?),
104|        _ => return Err(err("native creation sequence is missing or corrupt")),
105|    };
106|    let mut sorted = rows.iter().collect::<Vec<_>>();
107|    sorted.sort_by_key(|r| r.number);
108|    let mut expected = 1i64;
109|    for row in sorted {
110|        if row.number != expected
111|            || (row.number < next && row.phase != "complete")
112|            || (row.number == next && (row.phase == "complete" || row.request.operation_id != pending))
113|            || row.number > next
114|        { return Err(err("native creation history is incomplete; refusing sequence recovery")); }
115|        expected = expected.checked_add(1).ok_or_else(|| err("native name sequence exhausted"))?;
116|    }
117|    if next < 1 || (pending.is_empty() && expected != next)
118|        || (!pending.is_empty() && next.checked_add(1) != Some(expected))
119|    { return Err(err("native sequence and pending fence disagree")); }
120|    Ok((next, pending))
121|}
122|
123|fn put_sequence(tx: &MultiTransaction, next: i64, pending: &str) -> std::result::Result<(), CozoError> {
124|    query(tx, "?[key,next,pending] <- [['default',$next,$pending]] :put native_container_sequence {key => next,pending}",
125|        BTreeMap::from([("next".into(), dv_int(next)), ("pending".into(), DataValue::Str(pending.into()))]))?;
126|    query(tx, "?[name,completed] <- [['native-container-sequence-v1',true]] :put schema_migrations {name => completed}", Params::new())?;
127|    Ok(())
128|}
129|
130|impl CozoGraphShuttle {
131|    pub fn native_creation_records(&self) -> std::result::Result<Vec<NativeCreationRecord>, CozoError> {
132|        let _guard = self.identity_transaction.lock().map_err(|_| err("identity transaction owner is poisoned"))?;
133|        let tx = self.db.multi_transaction(false);
134|        let rows = records(&tx)?;
135|        sequence(&tx, &rows)?;
136|        commit_checked(&tx)?;
137|        Ok(rows)
138|    }
139|
140|    /// `fresh` is the only permission to issue POST, returned after the barrier.
141|    /// Replays, including intent-only replays, may only read/reconcile.
142|    pub fn reserve_native_creation(&self, request: NativeCreationRequest, observed_names: &[String])
143|        -> std::result::Result<(NativeCreationRecord, bool), CozoError>
144|    {
145|        if self.identity_directory.is_none() { return Err(err("native allocation requires persistent Cozo")); }
146|        if uuid::Uuid::parse_str(&request.operation_id).map_or(true, |id| id.to_string() != request.operation_id)
147|            || request.actor_id.is_empty() || request.caller_session.is_empty() || request.caller_genesis.is_empty()
148|            || !matches!(request.owner_kind.as_str(), "identity" | "project" | "incus")
149|            || request.logical_target.is_empty() || request.schema_hash.is_empty() || !valid_root_repair_digest(&request.request_digest)
150|            || request.request_json.len() > 65536
151|        { return Err(err("invalid native creation intent")); }
152|        let _guard = self.identity_transaction.lock().map_err(|_| err("identity transaction owner is poisoned"))?;
153|        self.sync_identity_store()?;
154|        let tx = self.db.multi_transaction(true);
155|        let rows = records(&tx)?;
156|        let (next, pending) = sequence(&tx, &rows)?;
157|        for name in observed_names.iter().filter(|n| is_numbered_native_name(n)) {
158|            if !rows.iter().any(|row| &row.name == name) {
159|                return Err(err("untracked ID-N native name; refusing allocation or max+1 recovery"));
160|            }
161|        }
162|        if let Some(row) = rows.iter().find(|row| row.request.operation_id == request.operation_id) {
163|            if row.request != request { return Err(err("native operation_id reused with different caller or request")); }
164|            commit_checked(&tx)?;
165|            return Ok((row.clone(), false));
166|        }
167|        if !pending.is_empty() { return Err(err("native creation unresolved; reconcile the owning operation before allocating another name")); }
168|        if request.owner_kind != "incus" && rows.iter().any(|row| row.request.owner_kind == request.owner_kind
169|            && row.request.logical_target == request.logical_target && observed_names.contains(&row.name))
170|        { return Err(err("logical target already has a native container; retain its binding")); }
171|        next.checked_add(1).ok_or_else(|| err("native name sequence exhausted"))?;
172|        let record = NativeCreationRecord { request, number: next, name: format!("ID-{next}"), phase: "intent".into(), native_uuid: String::new() };
173|        if observed_names.contains(&record.name) { return Err(err("native name collision")); }
174|        put(&tx, &record)?;
175|        put_sequence(&tx, next, &record.request.operation_id)?;
176|        commit_checked(&tx)?;
177|        self.sync_identity_store()?;
178|        Ok((record, true))
179|    }
180|
181|    pub fn bind_native_creation(&self, expected: &NativeCreationRecord, native_uuid: &str)
182|        -> std::result::Result<NativeCreationRecord, CozoError>
183|    {
184|        if uuid::Uuid::parse_str(native_uuid).map_or(true, |id| id.to_string() != native_uuid) {
185|            return Err(err("native creation readback lacks canonical UUID"));
186|        }
187|        self.update_native_creation(expected, native_uuid, false)
188|    }
189|
190|    /// Called only after complete canonical SHM publication. No abort/reset API.
191|    pub fn complete_native_creation(&self, expected: &NativeCreationRecord)
192|        -> std::result::Result<NativeCreationRecord, CozoError>
193|    {
194|        self.update_native_creation(expected, &expected.native_uuid, true)
195|    }
196|
197|    fn update_native_creation(&self, expected: &NativeCreationRecord, native_uuid: &str, complete: bool)
198|        -> std::result::Result<NativeCreationRecord, CozoError>
199|    {
200|        let _guard = self.identity_transaction.lock().map_err(|_| err("identity transaction owner is poisoned"))?;
201|        let tx = self.db.multi_transaction(true);
202|        let rows = records(&tx)?;
203|        let (next, pending) = sequence(&tx, &rows)?;
204|        let current = rows.iter().find(|r| r.request.operation_id == expected.request.operation_id)
205|            .ok_or_else(|| err("native creation intent disappeared"))?;
206|        if current != expected { return Err(err("native creation compare/exchange conflict")); }
207|        if current.phase == "complete" {
208|            if current.native_uuid != native_uuid { return Err(err("native UUID changed")); }
209|            commit_checked(&tx)?;
210|            self.sync_identity_store()?;
211|            return Ok(current.clone());
212|        }
213|        if pending != current.request.operation_id || next != current.number
214|            || (!current.native_uuid.is_empty() && current.native_uuid != native_uuid)
215|            || (complete && current.phase != "bound")
216|        { return Err(err("native creation fence or UUID changed")); }
217|        let mut updated = current.clone();
218|        updated.native_uuid = native_uuid.into();
219|        updated.phase = if complete { "complete" } else { "bound" }.into();
220|        put(&tx, &updated)?;
221|        if complete { put_sequence(&tx, next.checked_add(1).ok_or_else(|| err("native sequence exhausted"))?, "")?; }
222|        commit_checked(&tx)?;
223|        self.sync_identity_store()?;
224|        Ok(updated)
225|    }
