1423|/// Resolve ownership from committed identity bindings and durable preparation
1424|/// intents, not from the spelling of an ID-N name.
1425|pub(crate) async fn identity_session_for_native(engine: &MutationEngine, name: &str)
1426|    -> anyhow::Result<Option<String>> {
1427|    let cozo = engine.identity_sled_store()?.cozo().clone();
1428|    let target = name.to_owned();
1429|    tokio::task::spawn_blocking(move || -> anyhow::Result<Option<String>> {
1430|        let rows = cozo.native_creation_records()?;
1431|        if let Some(row) = rows.iter().find(|row| row.name == target) {
1432|            if row.request.owner_kind == "identity" {
1433|                return Ok(Some(row.request.logical_target.clone()));
1434|            }
1435|            anyhow::ensure!(row.phase == "complete", "native target has unresolved creation");
1436|            return Ok(None);
1437|        }
1438|        let state = cozo.read_identity_recovery_state(0)?;
1439|        let mut owner = None;
1440|        for revision in state.identities {
1441|            if let Some(record) = revision.record {
1442|                if !record.instance_json.is_empty() {
1443|                    let instance: IncusInstance = serde_json::from_str(&record.instance_json)?;
1444|                    if instance.name == target {
1445|                        anyhow::ensure!(owner.is_none(), "duplicate identity native binding");
1446|                        owner = Some(record.session_id);
1447|                    }
1448|                }
1449|            }
1450|        }
1451|        if owner.is_none() && uuid::Uuid::parse_str(&target).is_ok_and(|id| id.to_string() == target) {
1452|            owner = Some(target);
1453|        }
1454|        Ok(owner)
1455|    }).await?
