164|pub(crate) async fn verified_session(
165|    engine: &MutationEngine,
166|    actor: &str,
167|    session: Option<&str>,
168|    genesis: Option<&str>,
169|) -> Result<String> {
170|    let session = session
171|        .filter(|id| !id.is_empty())
172|        .ok_or_else(|| anyhow!("verified session is required"))?;
173|    canonical_id(session)?;
174|    if let Some(external) = crate::external_mcp_session::verify_connected_session(
175|        engine, actor, session, genesis,
176|    ).await? {
177|        return Ok(external);
178|    }
179|    let sled = crate::identity_sled_dispatch::stored_session(engine, session)
180|        .await
181|        .context("identity credential projection is unavailable")?
182|        .ok_or_else(|| anyhow!("verified session does not exist"))?;
183|    if !sled.is_anchored()
184|        || sled.genesis.as_deref() != genesis
185|        || op_identity::session::derive_principal_id(&sled.wireguard_pubkey) != actor
186|        || sled
187|            .expires_at
188|            .is_some_and(|at| at != 0 && at <= chrono::Utc::now().timestamp())
189|    {
190|        bail!("verified session binding is invalid");
191|    }
192|    let principal =
193|        crate::human_principal_dispatch::resolve_key_for_assertion(&sled.wireguard_pubkey)
194|            .await
195|            .map_err(|_| anyhow!("principal registry is unavailable"))?
196|            .ok_or_else(|| anyhow!("session key is not registered"))?;
197|    if principal.revoked_at != 0 || principal.principal_id != actor {
198|        bail!("session principal is revoked or mismatched");
199|    }
200|    Ok(session.into())
