222|async fn dispatch_owned(
223|    engine: &MutationEngine,
224|    method: &str,
225|    args: &Value,
226|    actor: &str,
227|    session: Option<&str>,
228|    genesis: Option<&str>,
229|) -> Result<Value> {
230|    let session = verified_session(engine, actor, session, genesis).await?;
231|    let grants: BTreeSet<String> = load_capability_grants(actor).into_iter().collect();
232|    let required = match method {
233|        "create" => "project.create",
234|        "invite" | "revoke_member" | "select_agent" => "project.admin",
235|        "put_document" => "project.write",
236|        "resolve_context" | "select_context" | "get_context" => "chat.context",
237|        "get" | "list" | "accept_invite" | "list_documents" => "project.read",
238|        _ => bail!("unknown project method"),
239|    };
240|    if !grants.contains(required) {
241|        bail!("exact project capability grant is required");
242|    }
243|    // Serializes ACL changes with all data access: a revocation cannot race a
244|    // stale read/modify/write of the project document. Cross-process entry is
245|    // exclusively the bridge; Cozo's process lock prevents a second writer.
246|    let _lock = PROJECT_LOCK.lock().await;
247|    if method == "resolve_context" {
248|        let input: ResolveContextInput = serde_json::from_value(args.clone())?;
249|        return Ok(serde_json::to_value(
250|            resolve_context(engine, &session, &grants, input).await?,
251|        )?);
252|    }
253|    if method == "select_context" {
254|        let input: SelectContextInput = serde_json::from_value(args.clone())?;
255|        let selection = ChatContextSelection {
256|            mode: input.mode,
257|            project_id: input.project_id,
258|            personal_namespace: input.personal_namespace,
259|        };
260|        // Validate exactly as a turn would resolve it before persisting.
261|        let resolved = resolve_selection(engine, &session, &grants, &selection).await?;
262|        let document = serde_json::to_string(&selection)?;
263|        catalog(
264|            engine,
265|            "?[session_id, document] <- [[$session, $document]] :put chat_context_selection {session_id => document}",
266|            json!({"session": session, "document": document}),
267|        )
268|        .await?;
269|        return Ok(serde_json::to_value(resolved)?);
270|    }
271|    if method == "get_context" {
272|        let _: GetContextInput = serde_json::from_value(args.clone())?;
273|        return Ok(serde_json::to_value(
274|            current_chat_context(engine, &session, &grants).await?,
275|        )?);
276|    }
277|    if method == "list" {
278|        let _: EmptyInput = serde_json::from_value(args.clone())?;
279|        return Ok(serde_json::to_value(ProjectListOutput {
280|            projects: list_projects(engine)
281|                .await?
282|                .into_iter()
283|                .filter(|p| p.role_for(&session).is_some())
284|                .map(|p| view_for(p, &session))
285|                .collect(),
286|        })?);
287|    }
288|    if method == "create" {
289|        let input: CreateProjectInput = serde_json::from_value(args.clone())?;
290|        if input.title.trim().is_empty() || input.title.len() > 256 {
291|            bail!("project title must contain 1–256 bytes");
292|        }
293|        if !input.capability_ceiling.is_subset(&grants) {
294|            bail!("project ceiling cannot exceed creator's exact grants");
295|        }
296|        if !input.allowed_agents.is_subset(&known_agent_ids()) {
297|            bail!("project agent is not in the declared catalog");
298|        }
299|        let fingerprint = std::env::var("OP_PROJECT_IMAGE_FINGERPRINT")
300|            .context("project image fingerprint is not configured")?;
301|        let pool = std::env::var("OP_PROJECT_STORAGE_POOL")
302|            .context("project storage pool is not configured")?;
303|        // A failed/cancelled create is resumed from the exact private project
304|        // document, not replaced with a new UUID/name. Ready projects remain
305|        // separate projects when the caller explicitly creates again.
306|        let pending = list_projects(engine).await?.into_iter().filter(|p|
307|            p.status == ProjectStatus::Provisioning && p.owner_session_id == session
308|            && p.title == input.title && p.capability_ceiling == input.capability_ceiling
309|            && p.allowed_agents == input.allowed_agents).collect::<Vec<_>>();
310|        anyhow::ensure!(pending.len() <= 1, "ambiguous pending project creation");
311|        let id = pending.first().map(|p| p.project_id.clone())
312|            .unwrap_or_else(|| uuid::Uuid::new_v4().to_string());
313|        let persistence_path = project_path(&id)?.to_string_lossy().into_owned();
314|        let mut project = pending.into_iter().next().unwrap_or_else(|| Project {
315|            project_id: id.clone(),
316|            title: input.title,
317|            owner_session_id: session.clone(),
318|            container_id: id.clone(),
319|            status: ProjectStatus::Provisioning,
320|            persistence_path,
321|            members: vec![],
