    let store = engine.identity_sled_store()?.clone();
    let lifecycle = store.lifecycle_lock(session_id).await.lock_owned().await;
    Ok(IdentityIncusTargetGuard {
        _lifecycle: lifecycle,
        store,
        session_id: session_id.to_string(),
    })
}

