112|    pub fn reserve_native_creation(&self, request: NativeCreationRequest, observed_names: &[String])
113|        -> std::result::Result<(NativeCreationRecord, bool), CozoError>
114|    {
115|        if self.identity_directory.is_none() { return Err(err("native allocation requires persistent Cozo")); }
