117|            || request.actor_id.is_empty() || request.caller_session.is_empty() || request.caller_genesis.is_empty()
118|            || !matches!(request.owner_kind.as_str(), "identity" | "project" | "incus")
119|            || request.logical_target.is_empty() || request.schema_hash.is_empty() || !valid_root_repair_digest(&request.request_digest)
