165|    fn update_native_creation(&self, expected: &NativeCreationRecord, native_uuid: &str, complete: bool)
166|        -> std::result::Result<NativeCreationRecord, CozoError>
167|    {
168|        let _guard = self.identity_transaction.lock().map_err(|_| err("identity transaction owner is poisoned"))?;
169|        let tx = self.db.multi_transaction(true);
170|        let rows = records(&tx)?;
171|        let (next, pending) = sequence(&tx, &rows)?;
172|        let current = rows.iter().find(|r| r.request.operation_id == expected.request.operation_id)
173|            .ok_or_else(|| err("native creation intent disappeared"))?;
174|        if current != expected { return Err(err("native creation compare/exchange conflict")); }
175|        if current.phase == "complete" {
176|            if current.native_uuid != native_uuid { return Err(err("native UUID changed")); }
177|            commit_checked(&tx)?;
178|            self.sync_identity_store()?;
179|            return Ok(current.clone());
180|        }
181|        if pending != current.request.operation_id || next != current.number
182|            || (!current.native_uuid.is_empty() && current.native_uuid != native_uuid)
183|            || (complete && current.phase != "bound")
184|        { return Err(err("native creation fence or UUID changed")); }
185|        let mut updated = current.clone();
186|        updated.native_uuid = native_uuid.into();
187|        updated.phase = if complete { "complete" } else { "bound" }.into();
188|        put(&tx, &updated)?;
189|        if complete { put_sequence(&tx, next.checked_add(1).ok_or_else(|| err("native sequence exhausted"))?, "")?; }
190|        commit_checked(&tx)?;
191|        self.sync_identity_store()?;
192|        Ok(updated)
193|    }
